    <div class="container mt-5">
        <div class="row justify-content-center">
            <div class="col-md-6">
                <h2 class="text-center mb-4">Trading Platform</h2>
                <form>
                    <div class="form-group">
                        <p class="mt-3 text-center">Welcome, John!</p>
